begin;
create table if not exists public.company_details(company_id uuid primary key references public.profiles(id),details jsonb not null default '{}',updated_at timestamptz not null default now());
create table if not exists public.company_verifications(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.profiles(id),decision text not null,reason text not null default '',reviewer_id uuid,created_at timestamptz not null default now());
create table if not exists public.complaints(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id),kind text not null,subject text not null,body text not null,status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')),assigned_to uuid,resolution text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.privacy_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),kind text not null check(kind in('access','correction','deletion','deactivation','privacy_concern')),body text not null,status text not null default 'open' check(status in('open','reviewing','resolved','declined')),response text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.jobs add column if not exists details jsonb not null default '{}';
alter table public.jobs add column if not exists deadline timestamptz;
alter table public.jobs add column if not exists salary_min numeric(14,2);
alter table public.jobs add column if not exists salary_max numeric(14,2);
alter table public.jobs add column if not exists salary_period text not null default 'month';
alter table public.jobs add column if not exists arrangement text not null default 'onsite' check(arrangement in('onsite','hybrid','remote'));
alter table public.jobs add column if not exists experience_years numeric not null default 0 check(experience_years between 0 and 80);
alter table public.jobs add column if not exists education_level text not null default '';
alter table public.jobs add column if not exists skills text[] not null default '{}';
alter table public.jobs add column if not exists positions integer not null default 1 check(positions>0);
alter table public.jobs add column if not exists moderation_reason text not null default '';
alter table public.jobs add column if not exists published_at timestamptz;
alter table public.jobs drop constraint if exists jobs_status_check;
alter table public.jobs add constraint jobs_status_check check(status in('draft','pending','approved','rejected','closed','corrections'));
alter table public.jobs drop constraint if exists jobs_salary_bounds;
alter table public.jobs add constraint jobs_salary_bounds check((salary_min is null or salary_min>=0) and (salary_max is null or salary_max>=coalesce(salary_min,0)));
alter table public.applications add column if not exists reference text;
update public.applications set reference='HAP-'||upper(replace(id::text,'-','')) where reference is null;
alter table public.applications alter column reference set default ('HAP-'||upper(replace(gen_random_uuid()::text,'-','')));
create unique index if not exists application_reference_unique on public.applications(reference);
alter table public.applications add column if not exists profile_snapshot jsonb;
alter table public.applications add column if not exists submission_key uuid;
alter table public.applications add column if not exists decision_reason text not null default '';
create unique index if not exists application_submission_key on public.applications(seeker_id,submission_key) where submission_key is not null;
alter table public.applications drop constraint if exists applications_status_check;
alter table public.applications add constraint applications_status_check check(status in('submitted','reviewing','shortlisted','interview','offered','rejected','hired','withdrawn'));
create table if not exists public.application_agreements(id uuid primary key default gen_random_uuid(),application_id uuid not null unique references public.applications(id),applicant_id uuid not null references auth.users(id),company_id uuid not null references public.profiles(id),job_id uuid not null references public.jobs(id),agreement_policy_id uuid not null references public.policy_documents(id),privacy_policy_id uuid not null references public.policy_documents(id),acknowledgment_version text not null default '1',acknowledged_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.application_documents(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),path text not null unique,original_name text not null,mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 5242880),created_at timestamptz not null default now());
create table if not exists public.application_status_history(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),previous_status text,status text not null,reason text not null default '',actor_id uuid,created_at timestamptz not null default now());
create table if not exists public.interviews(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),starts_at timestamptz not null,timezone text not null default 'Asia/Manila' check(timezone='Asia/Manila'),interview_type text not null check(interview_type in('in-person','online','phone')),venue text not null,instructions text not null default '',status text not null default 'scheduled' check(status in('scheduled','rescheduled','cancelled','completed')),outcome text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.interview_responses(id uuid primary key default gen_random_uuid(),interview_id uuid not null references public.interviews(id),user_id uuid not null references auth.users(id),response text not null check(response in('confirmed','declined','reschedule_requested')),note text not null default '',created_at timestamptz not null default now());
create table if not exists public.job_offers(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),terms text not null,expires_at timestamptz,status text not null default 'issued' check(status in('issued','accepted','declined','rescinded')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.application_messages(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),sender_id uuid not null references auth.users(id),body text not null check(length(body) between 1 and 4000),created_at timestamptz not null default now());
alter table public.career_resources add column if not exists details jsonb not null default '{}';
alter table public.career_resources add column if not exists archived boolean not null default false;
create or replace function public.can_review_application(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select public.has_current_session_ack() and exists(select 1 from public.applications a join public.jobs j on j.id=a.job_id where a.id=p_id and (public.is_admin() or (public.is_active_company() and j.company_id=auth.uid())))$$;
create or replace function public.can_read_application(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select public.has_current_session_ack() and exists(select 1 from public.applications a where a.id=p_id and (a.seeker_id=auth.uid() or public.can_review_application(a.id)))$$;
create or replace function public.job_is_eligible(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.jobs j join public.profiles p on p.id=j.company_id where j.id=p_id and j.status='approved' and p.role='company' and p.approval_status='active' and (j.deadline is null or j.deadline>now()))$$;
create or replace function public.record_application_change() returns trigger language plpgsql security definer set search_path='' as $$declare employer uuid;previous text;begin
if tg_op='UPDATE' then previous:=old.status;end if;
if tg_op='INSERT' or previous is distinct from new.status then
insert into public.application_status_history(application_id,previous_status,status,reason,actor_id) values(new.id,previous,new.status,new.decision_reason,auth.uid());
select company_id into employer from public.jobs where id=new.job_id;
insert into public.notifications(user_id,kind,message,entity_id) values(new.seeker_id,'application','Application '||new.reference||': '||new.status,new.id),(employer,'application','Application '||new.reference||': '||new.status,new.id);
insert into public.audit_logs(actor_id,action,entity_id,details) values(auth.uid(),'application_'||new.status,new.id,jsonb_build_object('previous',previous));end if;return new;end$$;
drop trigger if exists application_history on public.applications;
create trigger application_history after insert or update on public.applications for each row execute function public.record_application_change();
revoke insert,update,delete on public.applications from authenticated,anon;
revoke execute on function public.attach_application_document(uuid,text) from public,authenticated,anon;
create or replace function public.submit_agreed_application(p_job uuid,p_submission uuid,p_cover text,p_files jsonb,p_agreement uuid,p_privacy uuid,p_ack jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare j public.jobs;a public.applications;f jsonb;snapshot jsonb;path text;obj storage.objects;begin
perform public.require_workflow_access();if not public.is_active_seeker() then raise exception 'Active job seeker required' using errcode='42501';end if;
select * into a from public.applications where seeker_id=auth.uid() and submission_key=p_submission;
if found then return jsonb_build_object('id',a.id,'reference',a.reference);end if;
select * into j from public.jobs where id=p_job for update;
if not found or not public.job_is_eligible(p_job) then raise exception 'This vacancy is closed, expired, or unavailable';end if;
if p_submission is null or length(coalesce(p_cover,''))>8000 or p_files is null or jsonb_typeof(p_files)<>'array' or jsonb_array_length(p_files) not between 1 and 12 then raise exception 'Valid submission and 1–12 uploaded documents required';end if;
if p_agreement is distinct from public.current_policy('application') or p_agreement is null or p_privacy is distinct from public.current_policy('privacy') or p_privacy is null then raise exception 'Policy versions changed. Review the current application agreement';end if;
if p_ack->>'accurate' is distinct from 'true' or p_ack->>'sharing' is distinct from 'true' or p_ack->>'agreement' is distinct from 'true' then raise exception 'All application-specific acknowledgments required';end if;
if exists(select 1 from public.applications where job_id=p_job and seeker_id=auth.uid()) then raise exception 'You have already applied to this vacancy' using errcode='23505';end if;
for f in select * from jsonb_array_elements(p_files) loop
path:=f->>'path';if path is null or left(path,length(auth.uid()::text||'/staging/'||p_submission::text||'/'))<>auth.uid()::text||'/staging/'||p_submission::text||'/' then raise exception 'Document ownership mismatch' using errcode='42501';end if;
select * into obj from storage.objects where bucket_id='application-documents' and name=path;
if not found or coalesce((obj.metadata->>'size')::bigint,0) not between 1 and 5242880 or coalesce(obj.metadata->>'mimetype','') not in('application/pdf','image/jpeg','image/png','application/vnd.openxmlformats-officedocument.wordprocessingml.document') then raise exception 'Upload incomplete or document invalid';end if;end loop;
select jsonb_build_object('full_name',p.full_name,'email',p.email,'phone',p.phone,'location',p.location,'bio',p.bio,'personal',coalesce(i.personal,'{}'::jsonb)-array['birth_date','civil_status','nationality'],'education',coalesce(i.education,'{}'::jsonb),'background',coalesce(i.background,'{}'::jsonb)) into snapshot from public.profiles p left join public.seeker_information i on i.user_id=p.id where p.id=auth.uid();
insert into public.applications(job_id,seeker_id,cover_letter,document_paths,profile_snapshot,submission_key) values(p_job,auth.uid(),coalesce(p_cover,''),array(select value->>'path' from jsonb_array_elements(p_files)),snapshot,p_submission) returning * into a;
for f in select * from jsonb_array_elements(p_files) loop
select * into obj from storage.objects where bucket_id='application-documents' and name=f->>'path';
insert into public.application_documents(application_id,path,original_name,mime_type,size_bytes) values(a.id,f->>'path',left(f->>'name',240),obj.metadata->>'mimetype',(obj.metadata->>'size')::bigint);end loop;
insert into public.application_agreements(application_id,applicant_id,company_id,job_id,agreement_policy_id,privacy_policy_id) values(a.id,auth.uid(),j.company_id,j.id,p_agreement,p_privacy);
return jsonb_build_object('id',a.id,'reference',a.reference);end$$;
drop policy if exists "Applicant uploads own documents" on storage.objects;
create policy "Applicant uploads own documents" on storage.objects for insert to authenticated with check(bucket_id='application-documents' and (storage.foldername(name))[1]=auth.uid()::text and (storage.foldername(name))[2]='staging' and public.is_active_seeker() and public.has_current_session_ack());
drop policy if exists "Authorized users read documents" on storage.objects;
create policy "Authorized users read documents" on storage.objects for select to authenticated using(bucket_id='application-documents' and public.has_current_session_ack() and ((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.application_documents d where d.path=name and public.can_review_application(d.application_id)) or exists(select 1 from public.applications a where name=any(a.document_paths) and public.can_review_application(a.id))));
drop policy if exists "Owner removes unused staged files" on storage.objects;
create policy "Owner removes unused staged files" on storage.objects for delete to authenticated using(bucket_id='application-documents' and (storage.foldername(name))[1]=auth.uid()::text and not exists(select 1 from public.application_documents d where d.path=name) and not exists(select 1 from public.applications a where name=any(a.document_paths)));
drop policy if exists "Public read approved jobs" on public.jobs;
create policy "Public read approved jobs" on public.jobs for select to anon,authenticated using(public.job_is_eligible(id) or public.is_admin() or company_id=auth.uid());
drop policy if exists "Seeker and company and admin read applications" on public.applications;
create policy "Seeker and company and admin read applications" on public.applications for select to authenticated using(public.can_read_application(id));
create or replace function public.get_application_seeker_information(p_application_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare a public.applications;result jsonb;begin
if not public.can_review_application(p_application_id) then raise exception 'You do not have permission to view this applicant' using errcode='42501';end if;
select * into a from public.applications where id=p_application_id;if a.profile_snapshot is not null then return a.profile_snapshot;end if;
select jsonb_build_object('full_name',p.full_name,'email',p.email,'phone',p.phone,'location',p.location,'bio',p.bio,'education',coalesce(i.education,'{}'::jsonb),'background',coalesce(i.background,'{}'::jsonb),'legacy_current_record',true) into result from public.profiles p left join public.seeker_information i on i.user_id=p.id where p.id=a.seeker_id;return result;end$$;
do $$declare t text;begin foreach t in array array['company_details','company_verifications','complaints','privacy_requests','application_agreements','application_documents','application_status_history','interviews','interview_responses','job_offers','application_messages'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;
foreach t in array array['company_verifications','application_agreements','application_status_history','interview_responses','application_messages'] loop execute format('drop trigger if exists protect_history on public.%I',t);execute format('create trigger protect_history before update or delete on public.%I for each row execute function public.immutable_workflow_record()',t);end loop;end$$;
drop policy if exists company_private on public.company_details;
create policy company_private on public.company_details for select to authenticated using(company_id=auth.uid() or public.is_admin());
drop policy if exists verification_read on public.company_verifications;
create policy verification_read on public.company_verifications for select to authenticated using(company_id=auth.uid() or public.is_admin());
drop policy if exists complaint_access on public.complaints;
create policy complaint_access on public.complaints for select to authenticated using(reporter_id=auth.uid() or public.is_admin());
drop policy if exists privacy_access on public.privacy_requests;
create policy privacy_access on public.privacy_requests for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists agreement_access on public.application_agreements;
create policy agreement_access on public.application_agreements for select to authenticated using(public.can_read_application(application_id));
drop policy if exists document_access on public.application_documents;
create policy document_access on public.application_documents for select to authenticated using(public.can_read_application(application_id));
drop policy if exists history_access on public.application_status_history;
create policy history_access on public.application_status_history for select to authenticated using(public.can_read_application(application_id));
drop policy if exists interview_access on public.interviews;
create policy interview_access on public.interviews for select to authenticated using(public.can_read_application(application_id));
drop policy if exists response_access on public.interview_responses;
create policy response_access on public.interview_responses for select to authenticated using(exists(select 1 from public.interviews i where i.id=interview_id and public.can_read_application(i.application_id)));
drop policy if exists offer_access on public.job_offers;
create policy offer_access on public.job_offers for select to authenticated using(public.can_read_application(application_id));
drop policy if exists message_access on public.application_messages;
create policy message_access on public.application_messages for select to authenticated using(public.can_read_application(application_id));
revoke all on function public.can_review_application(uuid),public.can_read_application(uuid),public.job_is_eligible(uuid),public.submit_agreed_application(uuid,uuid,text,jsonb,uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.can_review_application(uuid),public.can_read_application(uuid),public.job_is_eligible(uuid),public.submit_agreed_application(uuid,uuid,text,jsonb,uuid,uuid,jsonb) to authenticated;
grant execute on function public.job_is_eligible(uuid) to anon;
commit;
